#!/usr/bin/env python3
"""
简易任务管理工具 - 展示群内协作流程示例代码
功能：创建、查看、完成、删除任务
"""

import json
from datetime import datetime
from typing import Optional

TASKS_FILE = "tasks.json"


class Task:
    """任务类"""

    def __init__(self, task_id: int, title: str, description: str = ""):
        self.id = task_id
        self.title = title
        self.description = description
        self.created_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.completed = False
        self.completed_at: Optional[str] = None

    def complete(self):
        """标记任务完成"""
        self.completed = True
        self.completed_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description,
            "created_at": self.created_at,
            "completed": self.completed,
            "completed_at": self.completed_at
        }

    @staticmethod
    def from_dict(data: dict) -> "Task":
        t = Task(data["id"], data["title"], data.get("description", ""))
        t.created_at = data["created_at"]
        t.completed = data["completed"]
        t.completed_at = data.get("completed_at")
        return t


class TaskManager:
    """任务管理器"""

    def __init__(self):
        self.tasks: list[Task] = []
        self.next_id = 1

    def load(self):
        """从文件加载任务"""
        try:
            with open(TASKS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                self.tasks = [Task.from_dict(t) for t in data.get("tasks", [])]
                self.next_id = data.get("next_id", 1)
        except FileNotFoundError:
            pass

    def save(self):
        """保存任务到文件"""
        data = {
            "tasks": [t.to_dict() for t in self.tasks],
            "next_id": self.next_id
        }
        with open(TASKS_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    def add(self, title: str, description: str = "") -> Task:
        """添加新任务"""
        task = Task(self.next_id, title, description)
        self.tasks.append(task)
        self.next_id += 1
        self.save()
        return task

    def list_tasks(self, show_completed: bool = True) -> list[Task]:
        """列出任务"""
        if show_completed:
            return self.tasks
        return [t for t in self.tasks if not t.completed]

    def complete_task(self, task_id: int) -> bool:
        """完成任务"""
        for task in self.tasks:
            if task.id == task_id:
                task.complete()
                self.save()
                return True
        return False

    def delete_task(self, task_id: int) -> bool:
        """删除任务"""
        for i, task in enumerate(self.tasks):
            if task.id == task_id:
                self.tasks.pop(i)
                self.save()
                return True
        return False


def print_menu():
    """打印菜单"""
    print("\n=== 简易任务管理工具 ===")
    print("1. 查看任务列表")
    print("2. 添加新任务")
    print("3. 完成任务")
    print("4. 删除任务")
    print("0. 退出")


def main():
    """主函数"""
    manager = TaskManager()
    manager.load()

    # 添加示例任务
    if not manager.tasks:
        manager.add("规划者分配任务", "规划者协调各机器人工作")
        manager.add("开发者编写代码", "实现具体功能模块")
        manager.add("测试验证功能", "确保代码质量")

    while True:
        print_menu()
        choice = input("\n请选择操作: ").strip()

        if choice == "1":
            tasks = manager.list_tasks(show_completed=False)
            if not tasks:
                print("暂无未完成的任务")
            else:
                print(f"\n共 {len(tasks)} 个任务:")
                for t in tasks:
                    print(f"  [{t.id}] {t.title} - {t.created_at}")

        elif choice == "2":
            title = input("任务标题: ").strip()
            if title:
                desc = input("任务描述(可选): ").strip()
                task = manager.add(title, desc)
                print(f"任务已创建: #{task.id} {task.title}")

        elif choice == "3":
            task_id = input("请输入任务ID: ").strip()
            if task_id.isdigit():
                if manager.complete_task(int(task_id)):
                    print("任务已完成！")
                else:
                    print("任务不存在")

        elif choice == "4":
            task_id = input("请输入任务ID: ").strip()
            if task_id.isdigit():
                if manager.delete_task(int(task_id)):
                    print("任务已删除")
                else:
                    print("任务不存在")

        elif choice == "0":
            print("再见！")
            break


if __name__ == "__main__":
    main()

